class SacrificeForMP extends CreatureScript {
  Locked = false;
  CanFloop() {
    let flag = true;
    if(this.Locked) {
        return false;
    }
    if(this.Owner == PlayerType.Opponent && flag) {
        let baseVal = this.Data.Form.BaseVal1;
        GameState.Instance.AddMagicPoints(this.Owner, baseVal);
        this.Locked = true;
        if(!GameState.Instance.HasLegalMove(this.Owner)) {
            flag = false;
        }
        this.Locked = false;
        GameState.Instance.AddMagicPoints(this.Owner, - baseVal);
    }
    return flag;
  }
  EvaluateAbility() {
    CardScript.ResetMods();
    CardScript.LaneMods[this.Owner][this.CurrentLane.Index].DEF = - this.Health;
    CardScript.APMods[this.Owner] = this.Data.Form.BaseVal1 - this.DetermineFloopCost();
    return CardScript.ScoreBoard(this.Owner);
  }
  Floop() {
    this.TargetList.Add(this);
    this.DoEffect();
  }
  DoResult(target) {
    this.GameInstance.AddMagicPoints(this.Owner, this.Data.Form.BaseVal1);
    this.GameInstance.RemoveCardFromPlay(target.Owner, target.CurrentLane.Index, CardType.Creature);
    this.GameInstance.DiscardCard(target.Owner, target.Data);
    return true;
  }
}

class DamageOpponentHealSelf extends CreatureScript {
  CanFloop() {
    if(this.CurrentLane.OpponentLane.HasCreature() || this.Damage > 0) {
        return true;
    }
    return false;
  }
  PopulateLaneMods() {
    if(this.Enemy != null) {
        CardScript.LaneMods[(opp(this.Owner))][this.Enemy.CurrentLane.Index].DEF = - Math.Min(this.Enemy.Health, this.Data.Val1);
    }
    CardScript.LaneMods[this.Owner][this.CurrentLane.Index].DEF = Math.Min(this.Damage, this.Data.Val2);
  }
  Floop() {
    if(this.CurrentLane.OpponentLane.HasCreature()) {
        let creature = this.CurrentLane.OpponentLane.GetCreature();
        this.TargetList.Add(creature);
    }
    if(this.Damage > 0) {
        this.TargetList.Add(this);
    }
    this.DoEffect();
  }
  DoResult(target) {
    let creatureScript = target;
    if(creatureScript == this) {
        creatureScript.Heal(this.Data.Val2);
    }
    else {
        creatureScript.TakeDamage(this, this.Data.Val1);
    }
    return true;
  }
}

class DestroyOpponentBuilding extends CreatureScript {
  CanFloop() {
    if(this.CurrentLane.OpponentLane.HasBuilding()) {
        return true;
    }
    return false;
  }
  EvaluateAbility() {
    let building = this.CurrentLane.OpponentLane.GetBuilding();
    building.StopTriggerEffects();
    building.OnCardLeftPlay(building);
    building.ResumeTriggerEffects();
    let result = this.GameInstance.ScoreBoard();
    building.StopTriggerEffects();
    building.OnCardEnterPlay(building);
    building.ResumeTriggerEffects();
    return result;
  }
  Floop() {
    let building = this.CurrentLane.OpponentLane.GetBuilding();
    this.TargetList.Add(building);
    this.DoEffect();
  }
  DoResult(target) {
    this.GameInstance.RemoveCardFromPlay(target.Owner, target.CurrentLane.Index, target.Data.Form.Type);
    this.GameInstance.DiscardCard(target.Owner, target.Data);
    return true;
  }
}

