class BlockSummon extends CreatureScript {
  CanFloop() {
    if(!this.CurrentLane.OpponentLane.Disabled) {
        return true;
    }
    return false;
  }
  EvaluateAbility() {
    let num = this.GameInstance.ScoreBoard();
    let num2 = this.GameInstance.ScoreLane(this.CurrentLane);
    let num3 = this.GameInstance.ScoreLane(this.CurrentLane.OpponentLane);
    let num4 = num2 - num3;
    return num + num4;
  }
  Floop() {
    this.CurrentLane.OpponentLane.Disabled = true;
    CWFloopActionManager.GetInstance().DoEffectLane(this, this.CurrentLane.OpponentLane.Index);
    this.TargetList.Clear();
  }
}

class ReturnTargetToHand extends CreatureScript {
  CanFloop() {
    if(this.GameInstance.HasCardTypeInPlay(opp(this.Owner), this.Data.Form.BaseVal1)) {
        return true;
    }
    return false;
  }
  EvaluateAbility() {
    let candidates = this.AITargetSelection(opp(this.Owner), this.Data.Form.BaseVal1);
    let cardScript = null;
    let num = 0;
    CardScript.ResetMods();
    CardScript.APMods[this.Owner] = - this.DetermineFloopCost();
    if(this.Data.Form.BaseVal1 == 0) {
        cardScript = CardScript.BestCandidateForAttack(candidates, - 1);
        CardScript.LaneMods[(opp(this.Owner))][cardScript.CurrentLane.Index].DEF = - (cardScript).Health;
        num = CardScript.ScoreBoard(this.Owner);
    }
    else {
        cardScript = CardScript.BestBuildingSacrifice(candidates);
        (cardScript).StopTriggerEffects();
        cardScript.OnCardLeftPlay(cardScript);
        num = CardScript.ScoreBoard(this.Owner);
        cardScript.OnCardEnterPlay(cardScript);
        (cardScript).ResumeTriggerEffects();
    }
    return num;
  }
  SelectionFilter(candidate) {
    if(candidate.HasCard(this.Data.Form.BaseVal1)) {
        return true;
    }
    return false;
  }
  ReturnToHand(target) {
    let script = target.GetScript(this.Data.Form.BaseVal1);
    this.TargetList.Add(script);
    this.DoEffect();
  }
  OnTargetSelected(target) {
    this.ReturnToHand(target);
    this.EndTargetSelection();
  }
  Floop() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(opp(this.Owner), this.Data.Form.BaseVal1, L10N("!!PICK_A_TARGET"));
        return;
    }
    let candidates = this.AITargetSelection(opp(this.Owner), this.Data.Form.BaseVal1);
    let creatureScript = CardScript.BestCandidateForAttack(candidates, - 1);
    this.ReturnToHand(creatureScript.CurrentLane);
  }
  DoResult(target) {
    this.GameInstance.RemoveCardFromPlay(target.Owner, target.CurrentLane.Index, target.Data.Form.Type);
    if(this.GameInstance.GetCardsInHand(target.Owner) < 7) {
        this.GameInstance.PlaceCardInHand(target.Owner, target.Data);
    }
    else {
        this.GameInstance.DiscardCard(target.Owner, target.Data);
    }
    return true;
  }
}

class BlockFloopTarget extends CreatureScript {
  StoredScore = 0;
  CanFloop() {
    let lanes = GameState.Instance.GetLanes(opp(this.Owner));
    for (const item of lanes) {
        if(item.HasCreature()) {
            let creature = item.GetCreature();
            if(!creature.FloopBlocked && (this.Owner == PlayerType.User || creature.CanFloop())) {
                return true;
            }
        }
    }
    return false;
  }
  SelectTarget() {
    let lanes = this.AITargetSelection(opp(this.Owner), SelectionType.Creature);
    let list = CardScript.LanesToCreatures(lanes);
    let num = (-2147483648);
    let creatureScript = null;
    for (const item of list) {
        if(item.FloopBlocked) {
            continue;
        }
        if(item instanceof BlockFloopTarget || (item instanceof BlockFloop && item.Enemy instanceof BlockFloopTarget)) {
            let num2 = this.GameInstance.ScoreBoard();
            if(creatureScript == null) {
                creatureScript = item;
                num = num2;
            }
            else if(num2 > num) {
                creatureScript = item;
                num = num2;
            }
            continue;
        }
        let num3 = this.GameInstance.ScoreBoard();
        if(item.CanFloop()) {
            num3 = item.EvaluateAbility();
        }
        if(creatureScript == null) {
            creatureScript = item;
            num = num3;
        }
        else if(num3 > num) {
            creatureScript = item;
            num = num3;
        }
    }
    this.StoredScore = num;
    return creatureScript;
  }
  EvaluateAbility() {
    this.SelectTarget();
    let num = this.GameInstance.ScoreBoard();
    let num2 = this.StoredScore - num;
    return num + num2;
  }
  SelectionFilter(candidate) {
    if(candidate.HasCreature()) {
        let creature = candidate.GetCreature();
        if(!creature.FloopBlocked) {
            return true;
        }
    }
    return false;
  }
  Block(target) {
    let creature = target.GetCreature();
    this.TargetList.Add(creature);
    this.DoEffect();
  }
  DoResult(target) {
    let creatureScript = target;
    creatureScript.FloopBlocked = true;
    return true;
  }
  OnTargetSelected(target) {
    this.Block(target);
    this.EndTargetSelection();
  }
  Floop() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(opp(this.Owner), SelectionType.Creature, L10N("!!TAP_CREATURE_TO_BLOCK_FLOOP"));
        return;
    }
    let creatureScript = this.SelectTarget();
    this.Block(creatureScript.CurrentLane);
  }
}

