class HealTargetAdjacent extends CreatureScript {
  CanFloop() {
    let lanes = GameState.Instance.GetLanes(this.Owner);
    for (const item of lanes) {
        if(item.HasCreature()) {
            let creature = item.GetCreature();
            if(creature.Damage > 0) {
                return true;
            }
        }
    }
    return false;
  }
  PopulateLaneMods() {
    let cWList = this.AITargetSelection(this.Owner, SelectionType.Creature);
    let creatureScript = CardScript.BestCandidateForHealing(cWList, this.Data.Val1, true);
    cWList.Remove(creatureScript.CurrentLane);
    let secondTarget = CardScript.BestCandidateForHealing(cWList, this.Data.Val1, true);
    creatureScript = this.MaximizeAdjacentTargets(creatureScript, secondTarget);
    CardScript.LaneMods[this.Owner][creatureScript.CurrentLane.Index].DEF = Math.Min(creatureScript.Damage, this.Data.Val1);
    let adjacentLanes = creatureScript.CurrentLane.AdjacentLanes;
    for (const lane of adjacentLanes) {
        if(lane != null && lane.HasCreature()) {
            let creature = lane.GetCreature();
            CardScript.LaneMods[this.Owner][lane.Index].DEF = Math.Min(creature.Damage, this.Data.Val1);
        }
    }
  }
  SelectionFilter(candidate) {
    if(candidate.HasCreature()) {
        let creature = candidate.GetCreature();
        if(creature.Damage > 0) {
            return true;
        }
    }
    let adjacentLanes = candidate.AdjacentLanes;
    for (const lane of adjacentLanes) {
        if(lane != null && lane.HasCreature()) {
            let creature2 = lane.GetCreature();
            if(creature2.Damage > 0) {
                return true;
            }
        }
    }
    return false;
  }
  DoHealing(target) {
    let creature = target.GetCreature();
    this.TargetList.Add(creature);
    let adjacentLanes = target.AdjacentLanes;
    for (const lane of adjacentLanes) {
        if(lane != null && lane.HasCreature()) {
            creature = lane.GetCreature();
            if(creature.Damage > 0) {
                this.TargetList.Add(creature);
            }
        }
    }
    this.DoEffect();
  }
  DoResult(target) {
    let creatureScript = target;
    creatureScript.Heal(this.Data.Val1);
    return true;
  }
  OnTargetSelected(target) {
    this.DoHealing(target);
    this.EndTargetSelection();
  }
  Floop() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(this.Owner, SelectionType.Creature, L10N("!!TAP_CREATURE_TO_HEAL"));
        return;
    }
    let cWList = this.AITargetSelection(this.Owner, SelectionType.Creature);
    let creatureScript = CardScript.BestCandidateForHealing(cWList, this.Data.Val1, true);
    cWList.Remove(creatureScript.CurrentLane);
    let secondTarget = CardScript.BestCandidateForHealing(cWList, this.Data.Val1, true);
    creatureScript = this.MaximizeAdjacentTargets(creatureScript, secondTarget);
    let currentLane = creatureScript.CurrentLane;
    this.DoHealing(currentLane);
  }
}

