class DrawCardsSacrifice extends CreatureScript {
  CanFloop() {
    if(this.GameInstance.GetCardsInHand(this.Owner) < 7 && this.GameInstance.GetDeck(this.Owner).CardCount() > 0) {
        return true;
    }
    return false;
  }
  EvaluateAbility() {
    CardScript.ResetMods();
    CardScript.LaneMods[this.Owner][this.CurrentLane.Index].DEF = - this.Health;
    CardScript.APMods[this.Owner] = - this.DetermineFloopCost();
    let num = CardScript.ScoreBoard(this.Owner);
    let num2 = Math.Min(7 - this.GameInstance.GetCardsInHand(this.Owner), this.Data.Val1);
    return num + num2 * 3;
  }
  Floop() {
    let baseVal = this.Data.Form.BaseVal1;
    for (let i = 0;
    i < baseVal;
    i++) {
        this.GameInstance.DrawCard(this.Owner);
    }
    this.TargetList.Add(this);
    this.DoEffect();
  }
  DoResult(target) {
    this.GameInstance.RemoveCardFromPlay(target.Owner, target.CurrentLane.Index, CardType.Creature);
    this.GameInstance.DiscardCard(target.Owner, target.Data);
    return true;
  }
}

