class FloopAdjacent extends CreatureScript {
  CanFloop() {
    let adjacentLanes = this.CurrentLane.AdjacentLanes;
    for (const lane of adjacentLanes) {
        if(lane != null && lane.HasCreature()) {
            let creature = lane.GetCreature();
            if(!(creature instanceof FloopAdjacent) && creature.CanFloop()) {
                return true;
            }
        }
    }
    return false;
  }
  EvaluateAbility() {
    let num = 0;
    let adjacentLanes = this.CurrentLane.AdjacentLanes;
    for (const lane of adjacentLanes) {
        if(lane == null || !lane.HasCreature()) {
            continue;
        }
        let creature = lane.GetCreature();
        if(!(creature instanceof FloopAdjacent) && creature.CanFloop()) {
            let num2 = creature.EvaluateAbility();
            if(num2 > num) {
                num = num2;
            }
        }
    }
    return num;
  }
  SelectionFilter(candidate) {
    if((this.CurrentLane.AdjacentLanes[0] == candidate || this.CurrentLane.AdjacentLanes[1] == candidate) && candidate.HasCreature()) {
        let creature = candidate.GetCreature();
        if(!(creature instanceof FloopAdjacent) && creature.CanFloop()) {
            return true;
        }
    }
    return false;
  }
  DoDamage(target) {
    let creature = target.GetCreature();
    this.TargetList.Add(creature);
    this.DoEffect();
  }
  DoResult(target) {
    let creatureScript = target;
    if(creatureScript.CanFloop()) {
        creatureScript.Floop();
        return false;
    }
    return true;
  }
  OnTargetSelected(target) {
    this.DoDamage(target);
    this.EndTargetSelection();
  }
  Floop() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(this.Owner, SelectionType.Creature, L10N("!!TAP_CREATURE_TO_FLOOP"));
        return;
    }
    let creatureScript = null;
    let num = 0;
    let adjacentLanes = this.CurrentLane.AdjacentLanes;
    for (const lane of adjacentLanes) {
        if(lane == null || !lane.HasCreature()) {
            continue;
        }
        let creature = lane.GetCreature();
        if(!(creature instanceof FloopAdjacent) && creature.CanFloop()) {
            let num2 = creature.EvaluateAbility();
            if(creatureScript == null || num2 > num) {
                creatureScript = creature;
                num = num2;
            }
        }
    }
    this.DoDamage(creatureScript.CurrentLane);
  }
}

