class RandomDiscardCard extends CreatureScript {
  CanFloop() {
    if(this.GameInstance.GetCardsInHand(this.Owner) >= 7) {
        return false;
    }
    let discardPile = GameState.Instance.GetDiscardPile(this.Owner);
    if(discardPile.Count > 0) {
        return true;
    }
    return false;
  }
  ScoreCards() {
    let discardPile = GameState.Instance.GetDiscardPile(this.Owner);
    let lanes = this.GameInstance.GetLanes(this.Owner);
    let num = 0;
    let num2 = 0;
    for (const item of discardPile) {
        if(item.Form.Type == CardType.Spell) {
            if(item.Form.CanPlay(this.Owner, - 1)) {
                num += item.EvaluateLanePlacement(this.Owner, null);
                num2++;
            }
            else {
                num += this.GameInstance.ScoreBoard() - item.Form.DetermineCost(this.Owner) * 1;
                num2++;
            }
            continue;
        }
        for (const item2 of lanes) {
            num += item.EvaluateLanePlacement(this.Owner, item2);
            num2++;
        }
    }
    return IDIV(num, num2);
  }
  EvaluateAbility() {
    return this.ScoreCards();
  }
  TakeCard(item) {
    GameState.Instance.RemoveCardFromDiscardPile(this.Owner, item);
    GameState.Instance.PlaceCardInHand(this.Owner, item);
    this.DoEffect();
  }
  Floop() {
    let discardPile = GameState.Instance.GetDiscardPile(this.Owner);
    let index = Random.Range(0, discardPile.Count);
    let item = discardPile[index];
    this.TakeCard(item);
  }
}

