class ShuffleHand extends CreatureScript {
  CanFloop() {
    return true;
  }
  EvaluateAbility() {
    let num = this.GameInstance.ScoreBoard();
    let num2 = this.GameInstance.ScoreCardsInHand(this.Owner);
    let num3 = 15 - num2;
    return num + num3;
  }
  Floop() {
    CWFloopActionManager.GetInstance().DoEffectHero(this, this.Owner);
  }
  DoResult(target) {
    let hand = this.GameInstance.GetHand(this.Owner);
    let deck = this.GameInstance.GetDeck(this.Owner);
    while(hand.Count > 0) {
        let newCard = hand[0];
        deck.AddCard(newCard);
        hand.RemoveAt(0);
    }
    deck.Shuffle();
    for (let i = 0;
    i < 5;
    i++) {
        this.GameInstance.DrawCard(this.Owner);
    }
    return true;
  }
}

