class ReturnHandsDrawCardsAddMP extends CreatureScript {
  StartTurn() {
    if(GameState.Instance.ExtraMagicPoints > 0) {
        this.GameInstance.AddMagicPoints(this.Owner, GameState.Instance.ExtraMagicPoints);
        GameState.Instance.ResetExtraMagicPoints();
    }
  }
  CanFloop() {
    return GameState.Instance.ExtraMagicPoints == 0;
  }
  EvaluateAbility() {
    let num = this.GameInstance.ScoreBoard();
    let num2 = this.GameInstance.ScoreCardsInHand(this.Owner);
    let num3 = 15 - num2;
    return num + num3;
  }
  Floop() {
    GameState.Instance.ExtraMagicPoints = this.Data.Form.BaseVal2;
    this.TargetList.Add(this);
    this.DoEffect();
  }
  DoResult(target) {
    let hand = this.GameInstance.GetHand(this.Owner);
    let deck = this.GameInstance.GetDeck(this.Owner);
    while(hand.Count > 0) {
        let newCard = hand[0];
        deck.AddCard(newCard);
        hand.RemoveAt(0);
    }
    deck.Shuffle();
    for (let i = 0;
    i < this.Data.Form.BaseVal1;
    i++) {
        this.GameInstance.DrawCard(this.Owner);
    }
    return true;
  }
}

class DEFBonusBuilding extends BuildingScript {
  static EvaluateLanePlacement(player, lane, item) {
    let result = GameState.Instance.ScoreBoard() - item.Form.DetermineCost(player) * 1;
    if(lane.HasCreature()) {
        CardScript.ResetMods();
        CardScript.LaneMods[player][lane.Index].DEF = item.Val1;
        CardScript.APMods[player] = - item.Form.DetermineCost(player);
        result = CardScript.ScoreBoard(player);
    }
    return result;
  }
  OnCardEnterPlay(script) {
    if(script == this) {
        if(this.CurrentLane.HasCreature()) {
            let creature = this.CurrentLane.GetCreature();
            this.ModifyDEF(creature, this.Data.Val1);
            this.TriggerEffects();
        }
    }
    else if(script.Data.Form.Type == CardType.Creature && script.CurrentLane == this.CurrentLane) {
        let script2 = script;
        this.ModifyDEF(script2, this.Data.Val1);
        this.TriggerEffects();
    }
  }
  OnCardLeftPlay(script) {
    if(script == this && this.CurrentLane.HasCreature()) {
        let creature = this.CurrentLane.GetCreature();
        this.ModifyDEF(creature, - this.Data.Val1);
    }
  }
}

