class DEFBonusCards extends BuildingScript {
  prevCount = 0;
  Initialized = false;
  static EvaluateLanePlacement(player, lane, item) {
    let result = GameState.Instance.ScoreBoard() - item.Form.DetermineCost(player) * 1;
    if(lane.HasCreature()) {
        let cardsInHand = GameState.Instance.GetCardsInHand(player);
        CardScript.ResetMods();
        CardScript.LaneMods[player][lane.Index].DEF = item.Val1 * cardsInHand;
        CardScript.APMods[player] = - item.Form.DetermineCost(player);
        result = CardScript.ScoreBoard(player);
    }
    return result;
  }
  OnCardEnterPlay(script) {
    let cardsInHand = this.GameInstance.GetCardsInHand(this.Owner);
    if(script == this) {
        if(this.CurrentLane.HasCreature()) {
            let creature = this.CurrentLane.GetCreature();
            this.ModifyDEF(creature, this.Data.Val1 * cardsInHand);
            this.TriggerEffects();
        }
        this.Initialized = true;
    }
    else if(script.Data.Form.Type == CardType.Creature && script.CurrentLane == this.CurrentLane) {
        let script2 = script;
        this.ModifyDEF(script2, this.Data.Val1 * cardsInHand);
        this.TriggerEffects();
    }
    this.prevCount = cardsInHand;
  }
  Update() {
    super.Update();
    if(!this.Initialized) {
        return;
    }
    let cardsInHand = this.GameInstance.GetCardsInHand(this.Owner);
    if(cardsInHand != this.prevCount) {
        let num = cardsInHand - this.prevCount;
        if(this.CurrentLane.HasCreature()) {
            let creature = this.CurrentLane.GetCreature();
            this.ModifyDEF(creature, this.Data.Val1 * num);
            this.TriggerEffects();
        }
        this.prevCount = cardsInHand;
    }
  }
  OnCardLeftPlay(script) {
    let cardsInHand = this.GameInstance.GetCardsInHand(this.Owner);
    if(script == this && this.CurrentLane.HasCreature()) {
        let creature = this.CurrentLane.GetCreature();
        this.ModifyDEF(creature, - this.Data.Val1 * cardsInHand);
    }
  }
}

