class BlockTargetFloop extends SpellScript {
  static StoredScore = 0;
  static CanPlay(player, lane, card) {
    let flag = CardScript.CanPlay(player, lane, card);
    if(flag) {
        let lanes = GameState.Instance.GetLanes(opp(player));
        for (const item of lanes) {
            if(item.HasCreature()) {
                let creature = item.GetCreature();
                if(!creature.FloopBlocked && (player == PlayerType.User || creature.CanFloop())) {
                    return true;
                }
            }
        }
        return false;
    }
    return flag;
  }
  static SelectTarget(Candidates) {
    let list = CardScript.LanesToCreatures(Candidates);
    let num = 0;
    let creatureScript = null;
    for (const item of list) {
        let num2 = GameState.Instance.ScoreBoard();
        if(item.CanFloop()) {
            num2 = item.EvaluateAbility();
        }
        if(creatureScript == null) {
            creatureScript = item;
            num = num2;
        }
        else if(num2 > num) {
            creatureScript = item;
            num = num2;
        }
    }
    BlockTargetFloop.StoredScore = num;
    return creatureScript;
  }
  static AIStaticSelection(player) {
    let cWList = new CWList();
    let instance = GameState.Instance;
    for (let i = 0;
    i < 4;
    i++) {
        let lane = instance.GetLane(player, i);
        if(lane.HasCreature()) {
            let creature = lane.GetCreature();
            if(!creature.FloopBlocked && creature.CanFloop()) {
                cWList.Add(lane);
            }
        }
    }
    return cWList;
  }
  static EvaluateLanePlacement(player, lane, item) {
    let candidates = BlockTargetFloop.AIStaticSelection(opp(player));
    BlockTargetFloop.SelectTarget(candidates);
    let num = GameState.Instance.ScoreBoard();
    let num2 = BlockTargetFloop.StoredScore - num;
    return num + num2 - item.Form.DetermineCost(player) * 1;
  }
  SelectionFilter(candidate) {
    if(candidate.HasCreature()) {
        let creature = candidate.GetCreature();
        if(!creature.FloopBlocked) {
            return true;
        }
    }
    return false;
  }
  ReturnTargetToHand(target) {
    let creature = target.GetCreature();
    this.TargetList.Add(creature);
    this.DoEffect();
  }
  OnTargetSelected(target) {
    this.ReturnTargetToHand(target);
    this.EndTargetSelection();
  }
  Cast() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(opp(this.Owner), SelectionType.Creature, L10N("!!PICK_A_CREATURE"));
        return;
    }
    let candidates = this.AITargetSelection(opp(this.Owner), SelectionType.Creature);
    let creatureScript = BlockTargetFloop.SelectTarget(candidates);
    this.ReturnTargetToHand(creatureScript.CurrentLane);
  }
  DoResult(target) {
    let creatureScript = target;
    creatureScript.FloopBlocked = true;
    return true;
  }
}

