class RandomCard extends SpellScript {
  static CanPlay(player, lane, card) {
    let flag = CardScript.CanPlay(player, lane, card);
    if(flag) {
        let deck = GameState.Instance.GetDeck(player);
        let cards = deck.GetCards();
        for (const item of cards) {
            if(item.Form.Type == card.BaseVal1) {
                return true;
            }
        }
        return false;
    }
    return flag;
  }
  static ScoreCards(player, item) {
    let cards = GameState.Instance.GetDeck(player).GetCards();
    let lanes = GameState.Instance.GetLanes(player);
    let num = 0;
    let num2 = 0;
    for (const item2 of cards) {
        if(item2.Form.Type != item.Form.BaseVal1) {
            continue;
        }
        if(item2.Form.Type == CardType.Spell) {
            if(item2.Form.ScriptName != "RandomCard") {
                if(item2.Form.CanPlay(player, - 1)) {
                    num += item2.EvaluateLanePlacement(player, null);
                    num2++;
                }
                else {
                    num += GameState.Instance.ScoreBoard() - item.Form.DetermineCost(player) * 1;
                    num2++;
                }
            }
            continue;
        }
        for (const item3 of lanes) {
            num += item2.EvaluateLanePlacement(player, item3);
            num2++;
        }
    }
    return IDIV(num, num2);
  }
  static EvaluateLanePlacement(player, lane, item) {
    return RandomCard.ScoreCards(player, item);
  }
  TakeCard(item) {
    GameState.Instance.RemoveCardFromDiscardPile(this.Owner, item);
    GameState.Instance.PlaceCardInHand(this.Owner, item);
  }
  CardFilter(item) {
    if(item.Form.Type == this.Data.Form.BaseVal1) {
        return true;
    }
    return false;
  }
  Cast() {
    CWFloopActionManager.GetInstance().DoEffectHero(this, this.Owner);
  }
  DoResult(target) {
    let cWList = new CWList();
    let cards = this.GameInstance.GetDeck(this.Owner).GetCards();
    for (const item2 of cards) {
        if(this.CardFilter(item2)) {
            cWList.Add(item2);
        }
    }
    let item = cWList.RandomItem();
    this.TakeCard(item);
    return true;
  }
}

