class DiscardForPoints extends SpellScript {
  static Locked = false;
  static CanPlay(player, lane, card) {
    if(DiscardForPoints.Locked) {
        return false;
    }
    let flag = CardScript.CanPlay(player, lane, card);
    if(flag && player == PlayerType.Opponent && flag) {
        GameState.Instance.AddMagicPoints(player, card.BaseVal1);
        DiscardForPoints.Locked = true;
        if(!GameState.Instance.HasLegalMove(player)) {
            flag = false;
        }
        DiscardForPoints.Locked = false;
        GameState.Instance.AddMagicPoints(player, - card.BaseVal1);
    }
    return flag;
  }
  static EvaluateLanePlacement(player, lane, item) {
    let num = item.Form.BaseVal1 - item.Form.DetermineCost(player);
    let cardsInHand = GameState.Instance.GetCardsInHand(player);
    return GameState.Instance.ScoreBoard() - cardsInHand * 3 + num * 1;
  }
  Cast() {
    CWFloopActionManager.GetInstance().DoEffectHero(this, this.Owner);
  }
  DoResult(target) {
    let hand = this.GameInstance.GetHand(this.Owner);
    while(hand.Count > 0) {
        let card = hand[0];
        this.GameInstance.DiscardCard(this.Owner, card);
        hand.RemoveAt(0);
    }
    this.GameInstance.AddMagicPoints(this.Owner, this.Data.Form.BaseVal1);
    return true;
  }
}

