class DestroyEntityForAction extends SpellScript {
  static Locked = false;
  static CanPlay(player, lane, card) {
    if(DestroyEntityForAction.Locked) {
        return false;
    }
    let flag = CardScript.CanPlay(player, lane, card);
    if(flag) {
        let num = GameState.Instance.CardCount(player, card.BaseVal1);
        if(num <= 0) {
            flag = false;
        }
        if(player == PlayerType.Opponent && flag) {
            GameState.Instance.AddMagicPoints(player, 4);
            DestroyEntityForAction.Locked = true;
            if(!GameState.Instance.HasLegalMove(player)) {
                flag = false;
            }
            DestroyEntityForAction.Locked = false;
            GameState.Instance.AddMagicPoints(player, - 4);
        }
    }
    return flag;
  }
  static AIStaticSelection(player, item) {
    let cWList = new CWList();
    let instance = GameState.Instance;
    for (let i = 0;
    i < 4;
    i++) {
        let lane = instance.GetLane(player, i);
        if(lane.HasCard(item.Form.BaseVal1)) {
            cWList.Add(lane);
        }
    }
    return cWList;
  }
  static EvaluateLanePlacement(player, lane, item) {
    let candidates = DestroyEntityForAction.AIStaticSelection(player, item);
    let cardScript = null;
    CardScript.ResetMods();
    let num = - item.Form.DetermineCost(player) * 1 + 4;
    if(item.Form.BaseVal1 == 0) {
        cardScript = CardScript.BestSacrifice(candidates);
        CardScript.LaneMods[player][cardScript.CurrentLane.Index].DEF = - (cardScript).Health;
        return CardScript.ScoreBoard(player) + num;
    }
    let buildingScript = CardScript.BestBuildingSacrifice(candidates);
    cardScript = buildingScript;
    buildingScript.StopTriggerEffects();
    cardScript.OnCardLeftPlay(cardScript);
    let result = GameState.Instance.ScoreBoard() + num;
    cardScript.OnCardEnterPlay(cardScript);
    buildingScript.ResumeTriggerEffects();
    return result;
  }
  SelectionFilter(candidate) {
    if(candidate.HasCard(this.Data.Form.BaseVal1)) {
        return true;
    }
    return false;
  }
  SacrificeTarget(target) {
    let script = target.GetScript(this.Data.Form.BaseVal1);
    this.TargetList.Add(script);
    this.DoEffect();
    CWFloopActionManager.GetInstance().DoEffectHero(this, this.Owner);
  }
  OnTargetSelected(target) {
    this.SacrificeTarget(target);
    this.EndTargetSelection();
  }
  Cast() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(this.Owner, this.Data.Form.BaseVal1, L10N("!!PICK_A_SACRIFICE"));
        return;
    }
    let candidates = this.AITargetSelection(this.Owner, this.Data.Form.BaseVal1);
    let cardScript = null;
    cardScript = ((this.Data.Form.BaseVal1 != 0) ? (CardScript.BestBuildingSacrifice(candidates)) : (CardScript.BestSacrifice(candidates)));
    this.SacrificeTarget(cardScript.CurrentLane);
  }
  DoResult(target) {
    if(target != null) {
        this.GameInstance.RemoveCardFromPlay(this.Owner, target.CurrentLane.Index, this.Data.Form.BaseVal1);
        this.GameInstance.DiscardCard(this.Owner, target.Data);
    }
    else {
        this.GameInstance.AddMagicPoints(this.Owner, 4);
    }
    return true;
  }
}

