class DestroyBuildingLane extends SpellScript {
  static CanPlay(player, lane, card) {
    let flag = CardScript.CanPlay(player, lane, card);
    if(flag) {
        if(GameState.Instance.BuildingCount(opp(player)) > 0 || GameState.Instance.CreatureCount(opp(player)) > 0) {
            return true;
        }
        return false;
    }
    return flag;
  }
  static AIStaticSelection(player) {
    let cWList = new CWList();
    let instance = GameState.Instance;
    for (let i = 0;
    i < 4;
    i++) {
        let lane = instance.GetLane(player, i);
        if(lane.HasBuilding() || lane.HasCreature()) {
            cWList.Add(lane);
        }
    }
    return cWList;
  }
  static EvaluateLanePlacement(player, lane, item) {
    let candidates = DestroyBuildingLane.AIStaticSelection(opp(player));
    let lane2 = CardScript.BestDoubleBuildingSacrifice(player, candidates);
    CardScript.ResetMods();
    CardScript.APMods[player] = - (item.Form.DetermineCost(player) * 1);
    if(lane2.HasBuilding()) {
        let building = lane2.GetBuilding();
        building.OnCardLeftPlay(building);
    }
    if(lane2.OpponentLane.HasBuilding()) {
        let building2 = lane2.OpponentLane.GetBuilding();
        building2.OnCardLeftPlay(building2);
    }
    if(lane2.HasCreature()) {
        CardScript.LaneMods[(opp(player))][lane2.Index].DEF = - lane2.GetCreature().Health;
    }
    if(lane2.OpponentLane.HasCreature()) {
        CardScript.LaneMods[player][lane2.Index].DEF = - lane2.OpponentLane.GetCreature().Health;
    }
    let result = CardScript.ScoreBoard(player);
    if(lane2.HasBuilding()) {
        let building3 = lane2.GetBuilding();
        building3.StopTriggerEffects();
        building3.OnCardEnterPlay(building3);
        building3.ResumeTriggerEffects();
    }
    if(lane2.OpponentLane.HasBuilding()) {
        let building4 = lane2.OpponentLane.GetBuilding();
        building4.StopTriggerEffects();
        building4.OnCardEnterPlay(building4);
        building4.ResumeTriggerEffects();
    }
    return result;
  }
  SelectionFilter(candidate) {
    if(candidate.HasBuilding() || candidate.HasCreature()) {
        return true;
    }
    return false;
  }
  DestroyTarget(target) {
    if(target.HasBuilding()) {
        let building = target.GetBuilding();
        this.TargetList.Add(building);
    }
    if(target.HasCreature()) {
        let creature = target.GetCreature();
        this.TargetList.Add(creature);
    }
    if(target.OpponentLane.HasBuilding()) {
        let building2 = target.OpponentLane.GetBuilding();
        this.TargetList.Add(building2);
    }
    if(target.OpponentLane.HasCreature()) {
        let creature2 = target.OpponentLane.GetCreature();
        this.TargetList.Add(creature2);
    }
    CWFloopActionManager.GetInstance().DoEffectNeutral(this, this.TargetList.ToArray());
    this.TargetList.Clear();
  }
  OnTargetSelected(target) {
    this.DestroyTarget(target);
    this.EndTargetSelection();
  }
  Cast() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(opp(this.Owner), SelectionType.Landscape, L10N("!!PICK_A_TARGET"));
        return;
    }
    let candidates = this.AITargetSelection(opp(this.Owner), SelectionType.Landscape);
    let target = CardScript.BestDoubleBuildingSacrifice(this.Owner, candidates);
    this.DestroyTarget(target);
  }
  DoResult(target) {
    this.GameInstance.RemoveCardFromPlay(target.Owner, target.CurrentLane.Index, target.Data.Form.Type);
    this.GameInstance.DiscardCard(target.Owner, target.Data);
    if(target.Data.Form.Type == CardType.Creature) {
        VOManager.Instance.PlayEvent(target.Owner, VOEvent.CreatureDestroyed);
    }
    else {
        VOManager.Instance.PlayEvent(target.Owner, VOEvent.BuildingDestroyed);
    }
    return true;
  }
}

