class DamageToATK extends SpellScript {
  static CanPlay(player, lane, card) {
    let flag = CardScript.CanPlay(player, lane, card);
    if(flag) {
        let lanes = GameState.Instance.GetLanes(player);
        for (const item of lanes) {
            if(item.HasCreature()) {
                let creature = item.GetCreature();
                if(creature.Damage > 0) {
                    return true;
                }
            }
        }
        return false;
    }
    return flag;
  }
  static BestCandidate(Candidates, player) {
    let list = CardScript.LanesToCreatures(Candidates);
    let list2 = [];
    let list3 = [];
    let list4 = [];
    let list5 = [];
    let list6 = [];
    let list7 = null;
    for (const item of list) {
        if(item.Enemy == null) {
            if(!item.CanWin) {
                if(item.Damage >= GameState.Instance.GetHealth(opp(player))) {
                    list2.Add(item);
                }
                else if(item.Damage > item.ATK) {
                    list3.Add(item);
                }
            }
        }
        else if(item.InDanger && !item.Enemy.InDanger) {
            if(item.Damage >= item.Enemy.Health) {
                list4.Add(item);
            }
            else {
                list6.Add(item);
            }
        }
        else if(!item.Enemy.InDanger && item.Damage >= item.Enemy.Health) {
            list5.Add(item);
        }
    }
    list7 = ((list2.Count > 0) ? list2 : ((list4.Count > 0) ? list4 : ((list5.Count > 0) ? list5 : ((list3.Count <= 0) ? list : list3))));
    let creatureScript = null;
    let creatureScript2 = null;
    for (const item2 of list7) {
        if(!list6.Contains(item2)) {
            if(creatureScript == null) {
                creatureScript = item2;
            }
            else if(item2.Damage > creatureScript.Damage) {
                creatureScript = item2;
            }
        }
        if(creatureScript2 == null) {
            creatureScript2 = item2;
        }
        if(item2.Damage > creatureScript2.Damage) {
            creatureScript2 = item2;
        }
    }
    if(creatureScript == null) {
        creatureScript = creatureScript2;
    }
    return creatureScript;
  }
  static AIStaticSelection(player, targetType) {
    let cWList = new CWList();
    let instance = GameState.Instance;
    for (let i = 0;
    i < 4;
    i++) {
        let lane = instance.GetLane(player, i);
        if(lane.HasCreature() && lane.GetCreature().Damage > 0) {
            cWList.Add(lane);
        }
    }
    return cWList;
  }
  static EvaluateLanePlacement(player, lane, item) {
    let candidates = DamageToATK.AIStaticSelection(player, SelectionType.Creature);
    let creatureScript = DamageToATK.BestCandidate(candidates, player);
    CardScript.ResetMods();
    CardScript.LaneMods[player][creatureScript.CurrentLane.Index].ATK = creatureScript.Damage - creatureScript.ATK;
    CardScript.APMods[player] = - item.Form.DetermineCost(player);
    return CardScript.ScoreBoard(player);
  }
  SelectionFilter(candidate) {
    if(candidate.HasCreature() && candidate.GetCreature().Damage > 0) {
        return true;
    }
    return false;
  }
  ReturnTarget(target) {
    let creature = target.GetCreature();
    this.TargetList.Add(creature);
    this.DoEffect();
  }
  OnTargetSelected(target) {
    this.ReturnTarget(target);
    this.EndTargetSelection();
  }
  Cast() {
    if(this.Owner == PlayerType.User) {
        this.StartTargetSelection(this.Owner, SelectionType.Creature, L10N("!!PICK_A_CREATURE"));
        return;
    }
    let candidates = this.AITargetSelection(this.Owner, SelectionType.Creature);
    let creatureScript = DamageToATK.BestCandidate(candidates, this.Owner);
    this.ReturnTarget(creatureScript.CurrentLane);
  }
  DoResult(target) {
    let creatureScript = target;
    let aTKMod = creatureScript.Damage - creatureScript.Data.Form.BaseATK;
    creatureScript.ATKMod = aTKMod;
    return true;
  }
}

