class ReturnCardTypeLeader extends LeaderScript {
  static StoredScore = 0;
  static CanPlay(player, lane, card) {
    let flag = LeaderScript.CanPlay(player, lane, card);
    if(flag) {
        if(GameState.Instance.GetCardsInHand(player) >= 7) {
            return false;
        }
        let discardPile = GameState.Instance.GetDiscardPile(player);
        let form = GameState.Instance.GetLeader(player).Form;
        for (const item of discardPile) {
            if(item.Form.Type == form.forCardType) {
                return true;
            }
        }
        return false;
    }
    return flag;
  }
  static SelectCard(player, item) {
    let discardPile = GameState.Instance.GetDiscardPile(player);
    let weightedList = new WeightedList();
    let lanes = GameState.Instance.GetLanes(player);
    let form = GameState.Instance.GetLeader(player).Form;
    for (const item2 of discardPile) {
        let type = item2.Form.Type;
        let forCardType = form.forCardType;
        if(type != NV(forCardType)) {
            continue;
        }
        if(item2.Form.Type == CardType.Spell) {
            if(item2.Form.CanPlay(player, - 1)) {
                let weight = item2.EvaluateLanePlacement(player, null);
                weightedList.AddSorted(item2, weight);
            }
            else {
                let weight2 = GameState.Instance.ScoreBoard();
                weightedList.AddSorted(item2, weight2);
            }
            continue;
        }
        for (const item3 of lanes) {
            let weight3 = item2.EvaluateLanePlacement(player, item3);
            weightedList.AddSorted(item2, weight3);
        }
    }
    let result = weightedList.TopCandidate();
    ReturnCardTypeLeader.StoredScore = weightedList.TopWeight();
    return result;
  }
  static EvaluateLanePlacement(player, lane, item) {
    ReturnCardTypeLeader.SelectCard(player, item);
    return ReturnCardTypeLeader.StoredScore;
  }
  TakeCard(item) {
    GameState.Instance.RemoveCardFromDiscardPile(this.Owner, item);
    GameState.Instance.PlaceCardInHand(this.Owner, item);
  }
  CardFilter(item) {
    let type = item.Form.Type;
    let forCardType = this.Leader.Form.forCardType;
    if(type == NV(forCardType)) {
        return true;
    }
    return false;
  }
  CardSelection(item) {
    this.TakeCard(item);
    this.CloseDiscardPile();
  }
  Cast() {
    CWFloopActionManager.GetInstance().DoEffectHero(this, this.Owner);
  }
  DoResult(target) {
    if(this.Owner == PlayerType.User) {
        this.OpenDiscardPile();
    }
    else {
        let item = ReturnCardTypeLeader.SelectCard(this.Owner, this.Data);
        this.TakeCard(item);
    }
    return true;
  }
}

