class BlockCardTypeDestroyBuildingsLeader extends LeaderScript {
  static CanPlay(player, lane, card) {
    let flag = LeaderScript.CanPlay(player, lane, card);
    let leader = GameState.Instance.GetLeader(player);
    if(flag) {
        let hand = GameState.Instance.GetHand(opp(player));
        let num = 0;
        for (const item of hand) {
            let type = item.Form.Type;
            let forCardType = leader.Form.forCardType;
            if(type == NV(forCardType)) {
                num++;
            }
        }
        if(num > 0) {
            return true;
        }
        if(GameState.Instance.HasCardTypeInPlay(opp(player), CardType.Building)) {
            return true;
        }
        return false;
    }
    return flag;
  }
  static EvaluateLanePlacement(player, lane, item) {
    let lanes = GameState.Instance.GetLanes(opp(player));
    for (const item2 of lanes) {
        if(item2.HasBuilding()) {
            let building = item2.GetBuilding();
            building.OnCardLeftPlay(building);
        }
    }
    let num = GameState.Instance.ScoreBoard();
    for (const item3 of lanes) {
        if(item3.HasBuilding()) {
            let building2 = item3.GetBuilding();
            building2.StopTriggerEffects();
            building2.OnCardEnterPlay(building2);
            building2.ResumeTriggerEffects();
        }
    }
    let hand = GameState.Instance.GetHand(opp(player));
    let form = GameState.Instance.GetLeader(player).Form;
    let num2 = 0;
    for (const item4 of hand) {
        let type = item4.Form.Type;
        let forCardType = form.forCardType;
        if(type == NV(forCardType)) {
            num2++;
        }
    }
    if(item != null) {
        num = num + num2 * 3 - item.Form.DetermineCost(player) * 1;
    }
    return num;
  }
  Cast() {
    let lanes = this.GameInstance.GetLanes(opp(this.Owner));
    let num = 0;
    for (const item of lanes) {
        if(item.HasBuilding()) {
            num++;
            let building = item.GetBuilding();
            this.TargetList.Add(building);
        }
    }
    let hand = GameState.Instance.GetHand(opp(this.Owner));
    let form = GameState.Instance.GetLeader(this.Owner).Form;
    let num2 = 0;
    for (const item2 of hand) {
        let type = item2.Form.Type;
        let forCardType = form.forCardType;
        if(type == NV(forCardType)) {
            num2++;
        }
    }
    if(num2 > 0) {
        this.TargetList.Add(null);
        CWFloopActionManager.GetInstance().DoEffectHero(this, opp(this.Owner));
    }
    if(num > 0) {
        this.DoEffect();
    }
  }
  DoResult(target) {
    if(target != null) {
        this.GameInstance.DiscardCard(target.Owner, target.Data);
        this.GameInstance.RemoveCardFromPlay(target.Owner, target.CurrentLane.Index, CardType.Building);
        VOManager.Instance.PlayEvent(target.Owner, VOEvent.BuildingDestroyed);
    }
    let gameInstance = this.GameInstance;
    let player = opp(this.Owner);
    let forCardType = this.Leader.Form.forCardType;
    gameInstance.EnableCasting(player, NV(forCardType), false);
    return true;
  }
}

